choose.when:
INSERT INTO author_content_stat (author_id, type, visibility, published_count)
VALUES (#{authorId}, #{type.code}, #{visibility.code}, #{delta})
ON DUPLICATE KEY UPDATE published_count = published_count + #{delta}

choose.otherwise:
UPDATE author_content_stat SET published_count = published_count + #{delta}
WHERE author_id = #{authorId} AND type = #{type.code} AND visibility = #{visibility.code}
  AND published_count >= -#{delta}

choose.when:
INSERT INTO audio_author_usage (audio_id, author_id, type, visibility, reference_count)
VALUES (#{audioId}, #{authorId}, #{type.code}, #{visibility.code}, #{delta})
ON DUPLICATE KEY UPDATE reference_count = reference_count + #{delta}

choose.otherwise:
UPDATE audio_author_usage SET reference_count = reference_count + #{delta}
WHERE audio_id = #{audioId} AND author_id = #{authorId}
  AND type = #{type.code} AND visibility = #{visibility.code}
  AND reference_count >= -#{delta}
